"use client";

import {
  useId,
  useRef,
  useState,
  type CSSProperties,
  type KeyboardEvent,
  type PointerEvent,
} from "react";

export type SolarPlanetId =
  | "mercury"
  | "venus"
  | "earth"
  | "mars"
  | "jupiter"
  | "saturn"
  | "uranus"
  | "neptune"
  | "pluto";

export interface SolarPlanet {
  id: SolarPlanetId;
  name: string;
  kind: "Planet" | "Dwarf planet";
  /** Mean distance from the Sun, in astronomical units. */
  distance: string;
  diameter: string;
  year: string;
  accent: string;
  description: string;
  detail: string;
  moons: string[];
}

export interface SolarExplorerProps {
  initialPlanet?: SolarPlanetId;
  onSelectPlanet?: (planet: SolarPlanet) => void;
  /** Overrides the built-in planet details dialog when supplied. */
  onReadMore?: (planet: SolarPlanet) => void;
  className?: string;
}

